/bin/bash -lc "rg -n 'timestamp|clock|timestamps|owner-sessions' results/telemetry/events.md | tail -12; python3 - <<'PY'
import subprocess,collections,json
for name in ['builds.jsonl','events.md','owner-sessions.jsonl']:
 path='results/telemetry/'+name
 ours,theirs=[subprocess.check_output(['git','show',f':{stage}:{path}']).decode() for stage in (2,3)]
 if name=='events.md': print(name,'branch text contained in incoming:',ours in theirs)
 elif name=='builds.jsonl': print(name,'branch only:',list((collections.Counter(ours.splitlines())-collections.Counter(theirs.splitlines())).elements()))
 else:
  om={json.loads(row)['name']:json.loads(row) for row in ours.splitlines()}; tm={json.loads(row)['name']:json.loads(row) for row in theirs.splitlines()}
  print('owner branch only names',om.keys()-tm.keys())
  for key in om:
   if key in tm:
    missing=om[key].keys()-tm[key].keys()
    if missing: print('incoming missing fields',key,missing)
PY"

